from __future__ import annotations

import re

_ALIGNMENTS = (None, "left", "right", "center")
_DELIMITER_CELL = re.compile(r":?-+:?")


def _escape_cell(value: object) -> str:
    """Return the Markdown text for one cell value."""
    if value is None:
        return ""
    return str(value).replace("|", "\\|")


def _split_row(line: str) -> list[str]:
    """Split a row on pipes, leaving escaped ``\\|`` sequences intact."""
    cells: list[str] = []
    current: list[str] = []
    index = 0
    while index < len(line):
        char = line[index]
        if char == "\\" and index + 1 < len(line) and line[index + 1] == "|":
            current.append("\\|")
            index += 2
        elif char == "|":
            cells.append("".join(current))
            current = []
            index += 1
        else:
            current.append(char)
            index += 1
    cells.append("".join(current))
    return cells


def _parse_row(line: str) -> list[str]:
    """Parse one table line into stripped, unescaped cells."""
    line = line.strip()
    cells = _split_row(line)

    if line.startswith("|"):
        cells = cells[1:]
    if line.endswith("|") and not line.endswith("\\|"):
        cells = cells[:-1]

    return [cell.strip().replace("\\|", "|") for cell in cells]


def _pad(text: str, width: int, alignment: str | None) -> str:
    """Pad cell text to *width* according to *alignment*."""
    padding = width - len(text)
    if alignment == "right":
        return " " * padding + text
    if alignment == "center":
        left = padding // 2
        return " " * left + text + " " * (padding - left)
    return text + " " * padding


def _delimiter_cell(width: int, alignment: str | None) -> str:
    """Build the delimiter cell for a column."""
    if alignment == "left":
        return ":" + "-" * (width - 1)
    if alignment == "right":
        return "-" * (width - 1) + ":"
    if alignment == "center":
        return ":" + "-" * (width - 2) + ":"
    return "-" * width


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    column_count = len(header)

    if align is None:
        alignments: list[str | None] = [None] * column_count
    else:
        try:
            alignments = list(align)
        except TypeError:
            raise ValueError("align must be a list of alignments") from None
        if len(alignments) != column_count:
            raise ValueError("align must have one entry per column")
        for alignment in alignments:
            if alignment not in _ALIGNMENTS:
                raise ValueError(f"invalid alignment: {alignment!r}")

    header_cells = [_escape_cell(value) for value in header]
    row_cells: list[list[str]] = []
    for row in rows:
        cells = list(row)
        if len(cells) > column_count:
            raise ValueError("row has more cells than the header")
        cells.extend([None] * (column_count - len(cells)))
        row_cells.append([_escape_cell(value) for value in cells])

    widths: list[int] = []
    for column in range(column_count):
        width = len(header_cells[column])
        for cells in row_cells:
            width = max(width, len(cells[column]))
        widths.append(max(width, 3))

    def line(cells: list[str]) -> str:
        return "| " + " | ".join(cells) + " |"

    lines = [line([_pad(header_cells[i], widths[i], alignments[i])
                   for i in range(column_count)])]
    lines.append(line([_delimiter_cell(widths[i], alignments[i])
                       for i in range(column_count)]))
    for cells in row_cells:
        lines.append(line([_pad(cells[i], widths[i], alignments[i])
                           for i in range(column_count)]))
    return "\n".join(lines)


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.splitlines()
    if len(lines) < 2:
        raise ValueError("a table needs a header and a delimiter line")

    header = _parse_row(lines[0])
    delimiter = _parse_row(lines[1])

    if len(delimiter) != len(header):
        raise ValueError("delimiter line has a different number of cells")

    alignments: list[str | None] = []
    for cell in delimiter:
        if _DELIMITER_CELL.fullmatch(cell) is None:
            raise ValueError(f"invalid delimiter cell: {cell!r}")
        if cell.startswith(":") and cell.endswith(":"):
            alignments.append("center")
        elif cell.startswith(":"):
            alignments.append("left")
        elif cell.endswith(":"):
            alignments.append("right")
        else:
            alignments.append(None)

    rows: list[list[str]] = []
    for line in lines[2:]:
        row = _parse_row(line)
        if len(row) != len(header):
            raise ValueError("row has a different number of cells")
        rows.append(row)

    return header, rows, alignments

