import random
import sys

sys.path.insert(0, "/private/tmp/tmp5uk5a2ge/pete/projects/devkit")

from devkit.table import format_table, parse_table

rng = random.Random(20261027)
alphabet = "abc XYZ019|_-~"


def value():
    choice = rng.randrange(6)
    if choice == 0:
        return None
    if choice == 1:
        return ""
    if choice == 2:
        return rng.randrange(-1000, 1000)
    if choice == 3:
        return rng.random()
    return "".join(rng.choice(alphabet) for _ in range(rng.randrange(0, 12)))


def expected_cell(item):
    return "" if item is None else str(item)


for trial in range(1000):
    ncols = rng.randrange(1, 6)
    nrows = rng.randrange(0, 7)
    header = [value() for _ in range(ncols)]
    rows = []
    for _ in range(nrows):
        width = rng.randrange(0, ncols + 1)  # never longer than header
        rows.append([value() for _ in range(width)])
    align = [rng.choice([None, "left", "right", "center"]) for _ in range(ncols)]

    text = format_table(header, rows, align)
    parsed_header, parsed_rows, parsed_align = parse_table(text)

    expected_header = [expected_cell(v).strip() for v in header]
    expected_rows = [
        ([expected_cell(v).strip() for v in row] + [""] * (ncols - len(row)))
        for row in rows
    ]

    assert parsed_header == expected_header, (trial, text, parsed_header, expected_header)
    assert parsed_rows == expected_rows, (trial, text, parsed_rows, expected_rows)
    assert parsed_align == align, (trial, text, parsed_align, align)

    lines = text.split("\n")
    assert len(lines) == nrows + 2
    assert all(line.startswith("| ") and line.endswith(" |") for line in lines)
    assert len({len(line) for line in lines}) == 1, (trial, text)

print("1000 randomized round-trip formatting tests passed")
